import itertools
import random

def check_r(r, S):
    P1 = []
    for i in range(len(S)):
        for j in range(len(S)):
            P1.append(S[i] - S[j])
    P1 = list(set(P1))

    P2 = []
    for p in P1:
        for q in P1:
            P2.append(3 * p * q * r)
    P2 = list(set(P2))

    # P3 elements: x^2 + y^2 - z^2 - w^2
    # Since we want to check if P2 is a subset of P3, 
    # we can't just build P3 if it's too large.
    # But we can check each element of P2.

    # To speed up, let's use a set for P3's components
    P1_sq = [x*x for x in P1]

    # We need to check if each e in P2 can be written as x2 + y2 - z2 - w2
    # which is equivalent to e + z2 + w2 = x2 + y2
    # We can pre-calculate all possible x2 + y2 and z2 + w2

    sums_of_two_sq = {}
    for i in range(len(P1_sq)):
        for j in range(i, len(P1_sq)):
            val = P1_sq[i] + P1_sq[j]
            if val not in sums_of_two_sq:
                sums_of_two_sq[val] = True

    # Wait, the number of sums_of_two_sq can be up to |P1|^2 / 2.
    # For |P1| = 13, |P1|^2 / 2 = 84.
    # For |P1| = 100, |P1|^2 / 2 = 5000.

    # We want to see if for each e in P2, there exist z, w, x, y such that
    # e = x^2 + y^2 - z^2 - w^2
    # which is e + z^2 + w^2 = x^2 + y^2

    # Let's pre-calculate all possible sums_of_two_sq
    possible_sums = set()
    for i in range(len(P1_sq)):
        for j in range(i, len(P1_sq)):
            possible_sums.add(P1_sq[i] + P1_sq[j])

    for e in P2:
        found = False
        for i in range(len(P1_sq)):
            for j in range(i, len(P1_sq)):
                if (e + P1_sq[i] + P1_sq[j]) in possible_sums:
                    found = True
                    break
            if found:
                break
        if not found:
            return False, e
    return True, None

