    P2 = list(set(P2))

    P1_sq = [x*x for x in P1]
    possible_sums = []
    for i in range(len(P1_sq)):
        for j in range(i, len(P1_sq)):
            possible_sums.append(P1_sq[i] + P1_sq[j])
    possible_sums = sorted(list(set(possible_sums)))

    for e in P2:
        found = False
        for i in range(len(P1_sq)):
            for j in range(i, len(P1_sq)):
                target = e + P1_sq[i] + P1_sq[j]
                # Binary search for target in possible_sums
                import bisect
                idx = bisect.bisect_left(possible_sums, target)
                if idx < len(possible_sums) and math.isclose(possible_sums[idx], target, rel_tol=1e-9, abs_tol=1e-9):
