def check_r_int(r_num, r_den, S):
    P1 = []
    for i in range(len(S)):
        for j in range(len(S)):
            P1.append(S[i] - S[j])
    P1 = list(set(P1))

    P2_num = []
    for p in P1:
        for q in P1:
            # 3 * p * q * r = 3 * p * q * r_num / r_den
            # We check if (3 * p * q * r_num) / r_den is in P3
            # To avoid floats, check if (3 * p * q * r_num) is in {r_den * x for x in P3}
            P2_num.append(3 * p * q * r_num)
    P2_num = list(set(P2_num))

    P1_sq = [x*x for x in P1]
    P3_vals_scaled = []
    for i in range(len(P1_sq)):
        for j in range(i, len(P1_sq)):
            P3_vals_scaled.append(P1_sq[i] + P1_sq[j])

    # P3 = {x2+y2-z2-w2}
    # 3*p*q*r_num / r_den = x2+y2-z2-w2
    # 3*p*q*r_num = r_den * (x2+y2-z2-w2)

    # Let's just check if each e in P2_num is in {r_den * (x2+y2-z2-w2)}
    # This is equivalent to: exists x2,y2,z2,w2 in P1_sq such that
    # e/r_den = x2+y2-z2-w2, i.e., e = r_den * (x2+y2-z2-w2)
    # or e/r_den + z2 + w2 = x2 + y2

    # Since we want to avoid floats, let's use:
    # e * r_den if r_den is positive? No.
    # If r_den is 3, then 3*p*q*r_num / 3 = p*q*r_num.
    # Let's just use: 3 * p * q * r_num = r_den * (x2 + y2 - z2 - w2)
    # 3 * p * q * r_num + r_den * (z2 + w2) = r_den * (x2 + y2)

    # To avoid large numbers, let's just use a set for the scaled P3.
    # But the question is whether 3*p*q*r_num / r_den is in P3.
    # For r=2/3, r_num=2, r_den=3.
    # 3*p*q*2/3 = 2pq.
    # We check if 2pq is in P3.

    # Let's re-implement
    P2 = []
    for p in P1:
        for q in P1:
            # We want to check 3 * p * q * (r_num/r_den)
            # Let's use fractions to be sure
            from fractions import Fraction
            P2.append(Fraction(3 * p * q * r_num, r_den))

    P3 = set()
    for i in range(len(P1_sq)):
        for j in range(i, len(P1_sq)):
            for k in range(len(P1_sq)):
                for l in range(k, len(P1_sq)):
                    P3.add(P1_sq[i] + P1_sq[j] - P1_sq[k] - P1_sq[l])

    for e in P2:
        if e not in P3:
            return False, e
    return True, None

