from fractions import Fraction

def check_r_fast(r_num, r_den, S):
    P1 = []
    for i in range(len(S)):
        for j in range(len(S)):
            P1.append(S[i] - S[j])
    P1 = list(set(P1))

    P1_sq = [x*x for x in P1]
    Sums2 = set()
    for i in range(len(P1_sq)):
        for j in range(i, len(P1_sq)):
            Sums2.add(P1_sq[i] + P1_sq[j])

    P2 = []
    for p in P1:
        for q in P1:
            P2.append(Fraction(3 * p * q * r_num, r_den))
    P2 = list(set(P2))

    for e in P2:
        found = False
        for s2 in Sums2:
            if (e + s2) in Sums2:
                found = True
                break
        if not found:
            return False, e
    return True, None

